<script setup lang="ts">import { trailRoutes } from '~/data/routes';useSiteSeo('Ture','Kurirane trail ture slovenskih tekačev z višinskimi profili in ključnimi podatki.');const view=ref<'list'|'cards'|'map'>('list');const active=ref(trailRoutes[0]?.id)</script>
<template><div class="page shell"><header class="page-header"><p class="eyebrow">Kurirane poti</p><h1>Ture z razlogom.</h1><p>Ne še en GPX repozitorij, temveč izbor tur, h katerim se slovenski tekači vedno vračajo.</p></header><div class="route-view-switch view-switch" aria-label="Način prikaza tur"><button :class="{active:view==='list'}" @click="view='list'">Seznam</button><button :class="{active:view==='cards'}" @click="view='cards'">Kartice</button><button :class="{active:view==='map'}" @click="view='map'">Zemljevid</button></div><div v-if="view==='list'" class="tour-list"><NuxtLink v-for="(tour,index) in trailRoutes" :key="tour.id" :to="`/routes/${tour.slug}`"><div><p class="eyebrow">{{ tour.region }} · {{ tour.difficulty }}</p><h3>{{ tour.name }}</h3><span class="mono">{{ tour.distance.toLocaleString('sl-SI') }} KM · {{ tour.elevationGain.toLocaleString('sl-SI') }} M+</span></div><ElevationProfile compact/><strong>{{ tour.recommendedBy }} ↗</strong></NuxtLink></div><div v-else-if="view==='cards'" class="route-directory tour-card-grid"><RouteCard v-for="(tour,index) in trailRoutes" :key="tour.id" :route="tour" :index="index"/></div><div v-else class="tour-overview-map"><div class="tour-overview-stage"><svg viewBox="0 0 800 500"><path v-for="(tour,index) in trailRoutes" :key="tour.id" :class="{active:active===tour.id}" :d="`M ${80+index*35} ${390-index*28} C ${180+index*20} ${80+index*19}, ${450-index*18} ${440-index*31}, ${710-index*24} ${90+index*35}`" @mouseenter="active=tour.id" @click="active=tour.id"/></svg><span class="mono">SKUPNI GPX ZEMLJEVID · PREDOGLED</span></div><aside><NuxtLink v-for="tour in trailRoutes" :key="tour.id" :to="`/routes/${tour.slug}`" :class="{active:active===tour.id}" @mouseenter="active=tour.id"><strong>{{ tour.name }}</strong><small>{{ tour.region }} · {{ tour.distance }} km</small></NuxtLink></aside></div></div></template>
